 [["Productiepakket en revisies compleet maken","Werkvoorbereider",4],["Leveranciersbevestigingen op juiste versies ontvangen","Inkoop",6],["Kwaliteit, contractdekking en vrijgavepakket controleren","Kwaliteitsmanager",8]],
 [["Productievoortgang en kwaliteitscontroles uitvoeren","Productieleider",7],["Transport, plaatsing en oplevering organiseren","Logistiek coördinator",12],["As-built, restpunten en financiële afsluiting afronden","Projectregiehouder",16]]
