function ensurePhaseTasks(p){
 data.tasks=data.tasks||[];
 for(let phase=0;phase<6;phase++){
  const marker="phase-template-"+p.id+"-"+phase;
  if(data.tasks.some(t=>t.id===marker))continue;
  const base=new Date();base.setDate(base.getDate()+phase*14);
  phaseTaskTemplates[phase].forEach((spec,index)=>{const due=new Date(base);due.setDate(due.getDate()+spec[2]);data.tasks.push({id:id(),projectId:p.id,title:spec[0],owner:spec[1],due:due.toISOString().slice(0,10),phase,priority:index===2?"Hoog":"Normaal",status:"Nog niet gestart",description:"Standaard faseactie. Leg resultaat en bewijsstukken vast in het projectdossier.",scope:"Standaard faseactie.",visibility:"internal",generated:true,createdAt:now()})});
  data.tasks.push({id:marker,projectId:p.id,title:"[systeem] standaardtaken aangemaakt fase "+(phase+1),phase,status:"Systeem",generated:true,visibility:"internal"});
 }
 localSave();
}
function phaseTaskState(p,phase){
 const tasks=(data.tasks||[]).filter(t=>t.projectId===p.id&&Number(t.phase)===phase&&!String(t.id).startsWith("phase-template-"));
 const open=tasks.filter(t=>!["Afgerond","Geannuleerd","Systeem"].includes(t.status));
 const overdue=open.filter(t=>t.due&&t.due<new Date().toISOString().slice(0,10));
 const missing=open.filter(t=>!t.owner||!t.owner.trim()||!t.due);
 return {tasks,open,overdue,missing,complete:tasks.some(t=>t.status!=="Systeem")&&open.length===0};
}
