 const required=[["contentComplete","Inhoudelijke informatie compleet"],["versionsCurrent","Juiste document- en modelversies gecontroleerd"],["competentApproval","Bevoegd akkoord vastgelegd"],...(phaseGateLabels[p.phase]||[])];
