 '<div class="card"><h2>Besluitenregister</h2>'+(data.decisions.length?data.decisions.map(d=>'<div class="record-row"><div><strong>'+esc(d.title)+'</strong><p>'+esc(d.text)+' · '+esc(projectName(d.projectId))+' · '+esc(phases[d.phase]||"")+'</p></div><div>'+pill(d.status)+' '+(d.status==="Concept"?btn("Goedkeuren","approve-decision:"+d.id,true):"")+'</div></div>').join(""):'<div class="empty">Nog geen besluiten vastgelegd.</div>')+'<div class="divider"></div><h3>Nieuw besluit registreren</h3><div class="field-grid">'+selectField("Project","decisionProject",p.id,data.projects.map(x=>[x.id,x.name]))+field("Onderwerp","decisionTitle","")+'</div><div class="field" style="margin-top:12px"><label>Besluit en onderbouwing</label><textarea id="decisionText"></textarea></div><div class="actions">'+btn("Besluit als concept registreren","add-decision")+'</div><div class="divider"></div><h3>Vrijgavehistorie</h3>'+(data.phaseReleases.filter(x=>x.projectId===p.id).map(x=>'<div class="record-row"><div><strong>'+esc(x.packageId||"Fasepakket")+'</strong><p>'+esc(x.phaseName||phases[x.phase])+' · '+esc(x.createdAt||"")+' · '+esc(x.approvedBy||"")+'</p></div>'+pill(x.status||"Vrijgegeven")+'</div>').join("")||'<div class="empty">Nog geen fasevrijgaven geregistreerd.</div>')+'</div>';
