async function saveCostInput(el){const c=data.costs.find(x=>x.id===el.dataset.cost);if(!c)return;c[el.dataset.prop]=el.type==="number"?Number(el.value):el.value;await persist("costs",c);toast("Financieel gegeven opgeslagen")}
async function action(a){if(a==="export-projects"){const rows=[["Projectcode","Projectnaam","Klant","Fase","Status","Aantal units","Bouwlagen","Locatie","Doelgroep","Planning"],...data.projects.map(p=>[p.code,p.name,(data.customers.find(c=>c.id===p.customerId)||{}).name||"",phases[p.phase]||"",p.status||"",p.unitCount,p.floorCount,p.location||"",p.target||"",p.planning||""])];const csv="\uFEFF"+rows.map(row=>row.map(v=>'"'+String(v??"").replace(/"/g,'""')+'"').join(";")).join("\r\n");const url=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));const link=document.createElement("a");link.href=url;link.download="thimo365-projectportfolio.csv";link.click();URL.revokeObjectURL(url);toast("Projectportfolio geëxporteerd");return}if(a==="bim-load-viewer"){await loadIfcViewer($("#ifcViewerFile")?.files?.[0]);return}if(a==="bim-frame-viewer"){frameIfcViewer();return}if(a==="bim-issue-from-selection"){await createIssueFromSelection();return}if(a.startsWith("bim-open-issue:")){openBimIssue(a.slice(15));return}if(a==="bim-import-ifc"){await importIfc();return}if(a==="bim-import-ids"){await importIds();return}if(a==="bim-run-ids"){await runIds();return}if(a==="bim-import-bcf"){await importBcf();return}if(a==="bim-export-bcf"){await exportBcf();return}if(a==="bim-add-issue"){const title=$("#bcfTitle")?.value||"";if(!title.trim()){toast("Vul een onderwerp in");return}await bimPersist("bimIssues",{id:id(),projectId:project().id,topicGuid:id(),title,status:$("#bcfStatus").value,priority:$("#bcfPriority").value,assignedTo:$("#bcfAssignee").value,description:$("#bcfDescription").value,components:$("#bcfComponent").value?[{ifcGuid:$("#bcfComponent").value}]:[],createdAt:now(),type:"Issue"});toast("BCF-issue geregistreerd");render();return}if(a.startsWith("go:")){page=a.slice(3);render();return}if(a.startsWith("open-project:")){projectId=a.slice(13);customerId=project().customerId;page="Klantprojecten";render();return}if(a.startsWith("choose-module:")){project().moduleId=a.slice(14);await persist("projects",project());render();return}if(a==="add-task"){const title=$("#newTaskTitle")?.value.trim()||"",owner=$("#newTaskOwner")?.value.trim()||"",due=$("#newTaskDue")?.value||"";if(!title||!owner||!due){toast("Vul taak, verantwoordelijke en deadline in");return}const t={id:id(),projectId:project().id,title,owner,due,phase:Number($("#newTaskPhase").value),priority:$("#newTaskPriority").value,status:"Nog niet gestart",description:$("#newTaskDescription").value,scope:$("#newTaskDescription").value,createdAt:now(),visibility:"internal"};data.tasks=data.tasks||[];data.tasks.push(t);await persist("tasks",t);render();toast("Projecttaak aangemaakt");return}if(a.startsWith("save-task:")){const t=(data.tasks||[]).find(x=>x.id===a.slice(10));if(!t)return;document.querySelectorAll('[data-task-edit="'+t.id+'"]').forEach(el=>{t[el.dataset.prop]=el.value});t.scope=t.description||"";await persist("tasks",t);render();toast("Taak en planning opgeslagen");return}if(a==="save-workflow"){const p=project();p.workflow=p.workflow||{};document.querySelectorAll("[data-workflow]").forEach(el=>{p.workflow[el.dataset.workflow]=el.value});await persist("projects",p);toast("Volledige projectuitwerking opgeslagen");render();return}if(a==="save-project"){await saveProject();return}if(a==="save-staff-project"){const p=project();await persist("projects",p);render();toast("Projectbasis opgeslagen");return}if(a==="save-proposal"){await saveProposal();return}if(a==="show-layout"){const el=$("#layoutPanel");if(el)el.scrollIntoView({behavior:"smooth",block:"start"});return}if(a==="add-change"){const p=project(),title=$("#changeTitle")?.value||"",reason=$("#changeReason")?.value||"";if(!title.trim()||!reason.trim()){toast("Vul onderwerp en aanleiding in");return}const x={id:id(),projectId:p.id,title,requester:$("#changeRequester").value,status:$("#changeStatus").value,reason,scope:$("#changeScope").value,technicalImpact:$("#changeTechnical").value,financialImpact:Number($("#changeFinancial").value||0),scheduleImpactDays:Number($("#changeSchedule").value||0),owner:$("#changeOwner").value,version:$("#changeVersion").value,evidence:$("#changeEvidence").value,blocking:true,visibility:"internal",createdAt:now()};data.changes.push(x);await persist("changes",x);render();toast("Wijziging geregistreerd; beoordeling blijft vereist");return}if(a.startsWith("publish-change:")){const x=(data.changes||[]).find(z=>z.id===a.slice(15));if(!x||x.status!=="Te controleren"||!x.evidence?.trim()){toast("Publiceren vereist controlebewijs en status Te controleren");return}x.status="Gepubliceerd";x.visibility="customer";x.blocking=false;x.publishedAt=now();await persist("changes",x);render();toast("Wijziging gepubliceerd voor klant");return}if(a==="add-document"){const p=project(),name=$("#docName")?.value||"";if(!name.trim()){toast("Vul een documentnaam in");return}const d={id:id(),projectId:p.id,name,documentId:$("#docId").value,version:$("#docVersion").value,status:$("#docStatus").value,audience:$("#docAudience").value,location:$("#docLocation").value,description:$("#docDescription").value,receivedAt:now(),visibility:"internal"};data.documents.push(d);await persist("documents",d);render();toast("Documentversie geregistreerd; bestand zelf is niet geüpload");return}if(a==="add-masterinfo"){const r={id:"mi-"+id(),category:"Nieuw",title:"Nieuw kennisgegeven",value:"",sourceType:"Fictieve demo",sourceName:"Demo-invoer platform",sourceUrl:"",status:"FICTIEF · NOG TE VALIDEREN",note:"Vul bron, inhoud en validatiestatus in."};data.masterInfo=data.masterInfo||[];data.masterInfo.push(r);await persist("masterInfo",r);render();toast("Kennisgegeven toegevoegd");return}if(a==="add-product"){const p={id:id(),code:"NIEUW-"+Date.now(),name:"Nieuwe module",category:"Standaardmodule",description:"Productinformatie nog in te vullen.",version:"0.1",status:"Concept",lengthM:null,widthM:null,bvoM2:null,owner:"Productbeheer"};data.products.push(p);await persist("products",p);render();toast("Module toegevoegd");return}if(a==="add-cost"){const p=product(project().moduleId),c={id:id(),productId:p.id,component:"Nieuw onderdeel",unit:"per project",cost:0,sale:0,validFrom:now().slice(0,10),status:"Concept"};data.costs.push(c);await persist("costs",c);render();toast("Nieuw onderdeel toegevoegd");return}if(a.startsWith("save-cost:")){const cid=a.slice(10),row=document.querySelector('[data-cost-row="'+CSS.escape(cid)+'"]'),c=data.costs.find(x=>x.id===cid);if(!row||!c)return;for(const el of row.querySelectorAll("[data-cost]")){const key=el.dataset.prop;c[key]=el.type==="number"?Number(el.value):el.value;}if(!c.component.trim()||!Number.isFinite(Number(c.cost))||!Number.isFinite(Number(c.sale))||Number(c.cost)<0||Number(c.sale)<0){toast("Controleer onderdeel en bedragen");return}await persist("costs",c);toast("Financieel onderdeel opgeslagen");return}if(a==="new-project"){const c={id:"c-"+id(),name:"NIEUWE DEMOKLANT",organisation:"Nog in te vullen",contact:""};const p={id:"p-"+id(),customerId:c.id,name:"Nieuw project",code:"TH-"+Date.now(),phase:0,status:"Intake",unitCount:1,floorCount:1,moduleId:data.products[0].id,location:"",budget:"",target:"Nog te bepalen",planning:"Nog te bepalen",layout:{},proposal:"Nog geen voorstel opgesteld.",messages:[],createdAt:now()};data.customers.push(c);data.projects.push(p);customerId=c.id;projectId=p.id;await persist("customers",c);await persist("projects",p);page="Klantprojecten";render();toast("Demoproject aangemaakt");return}if(a==="update-question"){const q=data.questions.find(x=>x.id===$("#questionStatusId")?.value);if(!q){toast("Selecteer een vraagstuk");return}q.status=$("#questionStatus").value;q.owner=$("#questionOwner").value||q.owner;q.answer=$("#questionAnswer").value||q.answer||"";if(["Besloten","Verwerkt","Gecontroleerd","Gesloten"].includes(q.status)&&q.answer)q.publicAnswer=q.answer;if(q.status==="Gesloten"||q.status==="Gecontroleerd")q.blocking=false;await persist("questions",q);render();toast("Vraagstuk bijgewerkt");return}if(a.startsWith("approve-decision:")){const d=data.decisions.find(x=>x.id===a.slice(17));if(d){d.status="Goedgekeurd";d.approvedBy="Thimo-medewerker";d.approvedAt=now();await persist("decisions",d);render();toast("Besluit goedgekeurd")}return}if(a==="save-phase-checks"){const p=project();let c=data.phaseChecks.find(x=>x.projectId===p.id&&x.phase===p.phase);if(!c){c={id:p.id+"-phase-"+p.phase,projectId:p.id,phase:p.phase,visibility:"internal"};data.phaseChecks.push(c)}await persist("phaseChecks",c);render();toast("Fasecontrole opgeslagen");return}if(a.startsWith("advance-phase:")){const p=data.projects.find(x=>x.id===a.slice(14));if(!p)return;const questionBlockers=data.questions.filter(q=>q.projectId===p.id&&q.blocking&&q.status!=="Gesloten"&&q.status!=="Gecontroleerd");const changeBlockers=(data.changes||[]).filter(x=>x.projectId===p.id&&x.blocking!==false&&!["Gepubliceerd","Afgewezen"].includes(x.status));const blockers=[...questionBlockers,...changeBlockers];const taskState=phaseTaskState(p,p.phase);const approved=data.decisions.some(d=>d.projectId===p.id&&d.status==="Goedgekeurd"&&d.phase===p.phase);const c=data.phaseChecks.find(x=>x.projectId===p.id&&x.phase===p.phase);const required=["contentComplete","versionsCurrent","competentApproval"];if(p.phase===0)required.push("moduleBasisConfirmed","requirementsConfirmed","regiehouderAssigned");if(p.phase===1)required.push("voApproved","doApproved","specialistReviews","clientSupplierScope","financialPlanning");if(p.phase===2)required.push("contractScopeComplete","supplierCoverage","commercialTermsApproved","signaturesComplete");if(p.phase===3)required.push("toApproved","technicalChecksComplete","deviationsResolved");if(p.phase===4)required.push("supplierConfirmed","packageComplete","contractCoverageConfirmed");if(p.phase===5)required.push("deliveryAccepted","asBuiltComplete","qualityEvidenceComplete","financialCloseComplete");if(blockers.length||!approved||!c||!required.every(k=>c[k])||!taskState.complete||taskState.missing.length){toast("Faseovergang geblokkeerd: faseacties, eigenaars, deadlines, controles of bevoegd besluit ontbreken");return}if(p.phase>=5){toast("Project is al in de laatste fase");return}const oldPhase=p.phase,release={id:id(),projectId:p.id,phase:oldPhase,phaseName:phases[oldPhase],nextPhase:oldPhase+1,packageId:"TH-"+p.code+"-F"+(oldPhase+1)+"-"+Date.now(),checks:{...c},approvedBy:"Bevoegde Thimo-medewerker",createdAt:now(),status:"Vrijgegeven",visibility:"customer"};data.phaseReleases.push(release);await persist("phaseReleases",release);p.phase++;p.status="In behandeling";await persist("projects",p);render();toast("Faseovergang vastgelegd");return}if(a==="add-decision"){const title=$("#decisionTitle")?.value||"",textValue=$("#decisionText")?.value||"";if(!title.trim()||!textValue.trim()){toast("Vul onderwerp en besluittekst in");return}const d={id:id(),projectId:$("#decisionProject").value,title,text:textValue,status:"Concept",phase:(data.projects.find(x=>x.id===$("#decisionProject").value)||{}).phase||0,visibility:"internal",createdAt:now(),createdBy:"Thimo-medewerker"};data.decisions.push(d);await persist("decisions",d);render();toast("Besluit als concept geregistreerd");return}if(a==="supplier-issue"){const t=$("#supplierIssueTitle")?.value||"",b=$("#supplierIssueText")?.value||"";if(!t.trim()||!b.trim()){toast("Vul onderwerp en omschrijving in");return}const q={id:id(),projectId:$("#supplierProject").value,title:"Leveranciersafwijking: "+t,body:b,status:"Open",owner:"Thimo-regiehouder",blocking:true,phase:project().phase,createdAt:now(),source:"supplier"};data.questions.push(q);await persist("questions",q);toast("Afwijking aan Thimo gemeld");render();return}}
document.addEventListener("click",async e=>{const b=e.target.closest("[data-action]");if(b)await action(b.dataset.action);const n=e.target.closest("[data-page]");if(n){page=n.dataset.page;render()}});
document.addEventListener("input",e=>{if(e.target.id==="projectSearch"){const q=e.target.value.trim().toLowerCase();let count=0;document.querySelectorAll("[data-project-search]").forEach(row=>{const show=row.dataset.projectSearch.includes(q);row.hidden=!show;if(show)count++});const label=$("#projectCount");if(label)label.textContent=count+" van "+data.projects.length+" projecten";}});
document.addEventListener("change",async e=>{const el=e.target;if(el.id==="roleSelect"){role=el.value;page=navs[role][0];await connect();return}if(el.id==="projectPicker"){projectId=el.value;customerId=((data.projectOptions||data.projects).find(p=>p.id===projectId)||{}).customerId||customerId;activeFloor=0;await connect();return}if(el.dataset.workflow){const p=project();p.workflow=p.workflow||{};p.workflow[el.dataset.workflow]=el.value;localSave();return}if(el.dataset.phasecheck){const p=project();let c=data.phaseChecks.find(x=>x.projectId===p.id&&x.phase===p.phase);if(!c){c={id:p.id+"-phase-"+p.phase,projectId:p.id,phase:p.phase,visibility:"internal"};data.phaseChecks.push(c)}c[el.dataset.phasecheck]=el.checked;localSave();return}if(el.dataset.field){const p=project();p[el.dataset.field]=el.type==="number"||el.dataset.field==="phase"?Number(el.value):el.value;if(el.dataset.field==="unitCount"||el.dataset.field==="floorCount"){distribute();render()}else localSave();return}if(el.dataset.masterinfo){const r=(data.masterInfo||[]).find(x=>x.id===el.dataset.masterinfo);if(r){r[el.dataset.prop]=el.value;await persist("masterInfo",r);toast("Moederinformatie opgeslagen")}return}if(el.dataset.product)await saveProductInput(el);if(el.dataset.cost)await saveCostInput(el);if(el.id==="floorSelect"){activeFloor=Number(el.value);render();}if(el.dataset.task){const t=data.tasks.find(x=>x.id===el.dataset.task);if(t){t.status=el.value;await persist("tasks",t);toast("Opdrachtstatus bijgewerkt")}}});
document.addEventListener("submit",async e=>{if(e.target.id==="chatForm"){e.preventDefault();const input=$("#chatInput");const value=input.value;input.value="";await sendChat(value)}});
document.addEventListener("keydown",e=>{if(e.target.id==="chatInput"&&e.key==="Enter"&&!e.shiftKey){e.preventDefault();$("#chatForm")?.requestSubmit()}});
document.addEventListener("dblclick",e=>{const unit=e.target.closest("[data-unit]");if(unit&&role==="client"){const n=Number(unit.dataset.unit),p=project(),floor=activeFloor,positions=p.layout[floor]||(p.layout[floor]={}),pos=positions[n]||{x:70,y:90,r:0};pos.r=(pos.r+90)%360;positions[n]=pos;localSave();persist("projects",p);render();toast("Unit 90° gedraaid")}});
let drag=null;
document.addEventListener("pointerdown",e=>{const g=e.target.closest("[data-unit]");if(!g||role!=="client")return;const svg=g.ownerSVGElement,rect=svg.getBoundingClientRect(),vb=svg.viewBox.baseVal;drag={unit:Number(g.dataset.unit),svg,rect,vb,startX:e.clientX,startY:e.clientY,origin:project().layout[activeFloor]?.[Number(g.dataset.unit)]||{x:70+(Math.floor(Number(g.dataset.unit)/Math.max(1,Number(project().floorCount)||1))%4)*160,y:90+Math.floor(Math.floor(Number(g.dataset.unit)/Math.max(1,Number(project().floorCount)||1))/4)*95,r:0}};g.setPointerCapture?.(e.pointerId)});
document.addEventListener("pointermove",e=>{if(!drag)return;const scaleX=drag.vb.width/drag.rect.width,scaleY=drag.vb.height/drag.rect.height;const x=Math.max(25,Math.min(625,drag.origin.x+(e.clientX-drag.startX)*scaleX)),y=Math.max(55,Math.min(325,drag.origin.y+(e.clientY-drag.startY)*scaleY));const p=project();p.layout[activeFloor]=p.layout[activeFloor]||{};p.layout[activeFloor][drag.unit]={x,y,r:drag.origin.r||0};const g=drag.svg.querySelector('[data-unit="'+drag.unit+'"]');if(g){const m=product(p.moduleId),w=m.lengthM?Math.max(60,Math.min(150,Number(m.lengthM)*12)):110,h=m.widthM?Math.max(34,Math.min(90,Number(m.widthM)*12)):54;g.setAttribute("transform","translate("+x+" "+y+") rotate("+(drag.origin.r||0)+" "+(w/2)+" "+(h/2)+")")}});
document.addEventListener("pointerup",()=>{if(drag){localSave();persist("projects",project());drag=null}});
$("#resetDemo").addEventListener("click",async()=>{if(!confirm("Alle demogegevens herstellen?"))return;data=structuredClone(seed);localSave();if(connected){try{const a=await api("/api/auth","POST",{role:"staff"});token=a.token;await api("/api/reset","POST",{});}catch(e){toast("Centrale reset niet uitgevoerd: "+e.message)}}role="client";page="Mijn project";projectId="p-parkzicht";customerId="c-parkzicht";activeFloor=0;await connect();toast("Demogegevens hersteld")});
connect();
